 const priorUndo=$('undoBtn').onclick;$('undoBtn').onclick=()=>{stopMelody();priorUndo();melodyUndo=[];melodyRedo=[];if(beachView==='melody')renderMelody();};
 melodyReady=true;$('navMelody').onclick=()=>setView('melody');
