 $('melodyView').addEventListener('click',e=>{const d=e.target.closest('[data-melody-duration]'),p=e.target.closest('[data-melody-pitch]');if(d){melodyDuration=d.dataset.melodyDuration;renderMelodyTools();}if(p)chooseMelodyPitch(p.dataset.melodyPitch+'/'+$('melodyOctave').value);});
 $('melodyDot').onclick=()=>{melodyDotted=!melodyDotted;renderMelodyTools();};$('melodyRest').onclick=()=>addMelodyNote('b/4',true);
 $('melodyModeAdd').onclick=()=>setMelodyEntryMode('add');$('melodyModeEdit').onclick=()=>setMelodyEntryMode('edit');
 $('melodyCanvas').onclick=e=>{
  if(!melodyGeometry||melodyPlaying)return;const {x,y}=melodyPointer(e);if(y<40||y>240)return;
  if(melodyEntryMode==='edit'){
   const notes=melodyGeometry.positions.filter(p=>!p.event.generated);const hit=notes.reduce((best,p)=>!best||Math.abs(p.x+5-x)<Math.abs(best.x+5-x)?p:best,null);
   if(hit){melodySelected=hit.event.index;renderMelody();}else melodyMessage('Add a note first, then switch to Edit.');return;
  }
  addMelodyNote(melodyGeometry.pitchAt(y));
 };
 $('melodyCanvas').onpointermove=e=>{
  if(!melodyGeometry||melodyEntryMode!=='add'||melodyPlaying)return;const {y}=melodyPointer(e),preview=$('melodyPitchPreview');preview.hidden=y<40||y>240;
  if(preview.hidden)return;const pitch=melodyGeometry.pitchAt(y),parts=pitch.split('/'),step=+parts[1]*7+'cdefgab'.indexOf(parts[0]);
  const snapped=melodyGeometry.bottom-(step-30)*melodyGeometry.spacing/2;preview.style.top=(snapped*melodyZoom)+'px';$('melodyPitchPreviewName').textContent=pitch.replace('/','').toUpperCase()+' · add next';
 };
 $('melodyCanvas').onpointerleave=()=>{$('melodyPitchPreview').hidden=true;};
