 $('melodyAddMeasure').onclick=()=>melodyChange(s=>{if(s.measures.length>=128)throw Error('A score can have up to 128 measures.');s.measures.splice(melodyBar+1,0,{notes:[],chords:[],reference:''});melodyBar++;melodySelected=null;});
