 $('melodyDeleteMeasure').onclick=()=>melodyChange(s=>{if(s.measures.length===1)s.measures[0]={notes:[],chords:[],reference:''};else s.measures.splice(melodyBar,1);melodyBar=Math.min(melodyBar,s.measures.length-1);melodySelected=null;});
