 $('melodySetChord').onclick=()=>{const name=$('melodyChord').value,at=+$('melodyChordAt').value;if(!name)return;melodyChange(s=>{const m=s.measures[melodyBar];m.chords=m.chords.filter(c=>c.at!==at);m.chords.push({at,name});});};
