 $('melodySave').onclick=()=>$('saveBtn').click();$('melodyListen').onclick=()=>melodyPlaying?stopMelody():playMelody();$('melodyPrint').onclick=printMelody;$('melodyPDFClose').onclick=()=>$('melodyPDFModal').close();
 for(const id of ['openVideoStudio','openPracticeSheet','newSong']){const b=$(id);if(b?.onclick){const action=b.onclick;b.onclick=e=>{stopMelody();return action(e);};}}
