 try{melodyGeometry=UkeMelodyRenderer.measure($('melodyCanvas'),song.notation,melodyBar,{width,scale:Math.min(3,(window.devicePixelRatio||1)*melodyZoom),lyricFont:17,chordFont:19,editable:true,entryMode:melodyEntryMode,selected:melodySelected,last:melodyBar===song.notation.measures.length-1});$('melodyCanvas').style.width=width*melodyZoom+'px';$('melodyCanvas').style.height=280*melodyZoom+'px';$('melodyZoomValue').textContent=Math.round(melodyZoom*100)+'%';}catch(e){melodyMessage('Could not draw this measure: '+e.message,true);return false;}return true;
